using System.ComponentModel.DataAnnotations;
using System.Globalization;
using System.Net.Http.Headers;
using System.Security.Claims;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.Http.Features;
using Microsoft.EntityFrameworkCore;

var builder = WebApplication.CreateBuilder(args);
var connection = builder.Configuration.GetConnectionString("Default")
    ?? "Host=localhost;Port=5432;Database=lectnote;Username=lectnote;Password=change_me";

builder.Services.AddDbContext<AppDbContext>(o => o.UseNpgsql(connection).UseSnakeCaseNamingConvention());
builder.Services.AddHttpClient<OpenAiTranscriptionService>();
builder.Services.AddScoped<IPasswordHasher<User>, PasswordHasher<User>>();
builder.Services.AddSingleton<TokenService>();
builder.Services.AddHostedService<TranscriptionWorker>();
builder.Services.AddCors(o => o.AddDefaultPolicy(p => p.WithOrigins(
    builder.Configuration.GetSection("Cors:Origins").Get<string[]>() ?? ["http://localhost:5173", "http://localhost:8080"])
    .AllowAnyHeader().AllowAnyMethod()));
builder.Services.Configure<FormOptions>(o => o.MultipartBodyLengthLimit = 100 * 1024 * 1024);

var app = builder.Build();
app.UseCors();
app.Use(async (ctx, next) => { await AuthMiddleware.TrySetUser(ctx, app.Services.GetRequiredService<TokenService>()); await next(); });

app.MapGet("/api/hello", async (AppDbContext db) => Results.Ok(new { message = "Hello from Lectnote API", studyGroups = await db.StudyGroups.CountAsync() }));
app.MapGet("/api/study-groups", async (AppDbContext db) => Results.Ok(await db.StudyGroups.AsNoTracking().OrderBy(x => x.Name).Select(x => new { x.Id, x.Name }).ToListAsync()));

app.MapPost("/api/auth/register", async (RegisterRequest req, AppDbContext db, IPasswordHasher<User> hasher) =>
{
    var error = req.Validate(); if (error is not null) return Results.BadRequest(new { error });
    var email = req.Email.Trim().ToLowerInvariant();
    if (await db.Users.AnyAsync(x => x.Email == email)) return Results.Conflict(new { error = "E-mail já registado." });
    if (!await db.StudyGroups.AnyAsync(x => x.Id == req.StudyGroupId)) return Results.BadRequest(new { error = "Grupo de estudo inválido." });
    var user = new User { FullName = req.FullName.Trim(), Email = email, StudyGroupId = req.StudyGroupId };
    user.PasswordHash = hasher.HashPassword(user, req.Password);
    db.Users.Add(user); await db.SaveChangesAsync();
    return Results.Created($"/api/users/{user.Id}", Dtos.User(user));
});
app.MapPost("/api/auth/login", async (LoginRequest req, AppDbContext db, IPasswordHasher<User> hasher, TokenService tokens) =>
{
    var user = await db.Users.SingleOrDefaultAsync(x => x.Email == req.Email.Trim().ToLowerInvariant());
    if (user is null || hasher.VerifyHashedPassword(user, user.PasswordHash, req.Password) == PasswordVerificationResult.Failed)
        return Results.Json(new { error = "Credenciais inválidas." }, statusCode: 401);
    return Results.Ok(new { token = tokens.Create(user), user = Dtos.User(user) });
});
app.MapPost("/api/auth/logout", (HttpContext ctx) => Require(ctx) is null ? Results.Json(new { error = "Autenticação necessária." }, statusCode: 401) : Results.NoContent());

app.MapGet("/api/courses", async (HttpContext ctx, AppDbContext db) =>
{
    var u = await RequireUser(ctx, db); if (u is null) return Unauthorized(); if (u.StudyGroupId is null) return Forbidden("O utilizador não pertence a um grupo.");
    return Results.Ok(await db.Courses.AsNoTracking().Where(x => x.StudyGroupId == u.StudyGroupId).OrderBy(x => x.Title).Select(x => new { x.Id, x.Title }).ToListAsync());
});
app.MapPost("/api/courses", async (CourseRequest req, HttpContext ctx, AppDbContext db) =>
{
    var u = await RequireUser(ctx, db); if (u is null) return Unauthorized(); if (u.StudyGroupId is null) return Forbidden("O utilizador não pertence a um grupo.");
    if (string.IsNullOrWhiteSpace(req.Title) || req.Title.Length > 200) return Bad("O título é obrigatório e deve ter até 200 caracteres.");
    var c = new Course { Title = req.Title.Trim(), StudyGroupId = u.StudyGroupId.Value }; db.Courses.Add(c); await db.SaveChangesAsync(); return Results.Created($"/api/courses/{c.Id}", new { c.Id, c.Title });
});
app.MapGet("/api/courses/{courseId:long}/lessons", async (long courseId, HttpContext ctx, AppDbContext db) =>
{
    var u = await RequireUser(ctx, db); if (u is null) return Unauthorized(); var c = await db.Courses.AsNoTracking().SingleOrDefaultAsync(x => x.Id == courseId && x.StudyGroupId == u.StudyGroupId); if (c is null) return NotFoundError("Curso não encontrado.");
    return Results.Ok(await db.Lessons.AsNoTracking().Where(x => x.CourseId == courseId).OrderBy(x => x.LessonDate).Select(x => new { id = x.Id, courseId = x.CourseId, topic = x.Topic, lessonDate = x.LessonDate }).ToListAsync());
});
app.MapPost("/api/courses/{courseId:long}/lessons", async (long courseId, LessonRequest req, HttpContext ctx, AppDbContext db) =>
{
    var u = await RequireUser(ctx, db); if (u is null) return Unauthorized(); var c = await db.Courses.SingleOrDefaultAsync(x => x.Id == courseId && x.StudyGroupId == u.StudyGroupId); if (c is null) return NotFoundError("Curso não encontrado.");
    if (string.IsNullOrWhiteSpace(req.Topic) || req.Topic.Length > 255 || !DateOnly.TryParse(req.LessonDate, out var date)) return Bad("Tópico ou data inválidos.");
    var l = new Lesson { CourseId = courseId, Topic = req.Topic.Trim(), LessonDate = date }; db.Lessons.Add(l); await db.SaveChangesAsync(); return Results.Created($"/api/lessons/{l.Id}", Dtos.Lesson(l));
});
app.MapGet("/api/study-group/members", async (HttpContext ctx, AppDbContext db) => { var u = await RequireUser(ctx, db); if (u is null) return Unauthorized(); return Results.Ok(await db.Users.AsNoTracking().Where(x => x.StudyGroupId == u.StudyGroupId && x.Id != u.Id).OrderBy(x => x.FullName).Select(x => new { id = x.Id, fullName = x.FullName }).ToListAsync()); });

app.MapPost("/api/notes", async (NoteRequest req, HttpContext ctx, AppDbContext db) => { var u = await RequireUser(ctx, db); if (u is null) return Unauthorized(); if (string.IsNullOrWhiteSpace(req.Title) || req.Title.Length > 255) return Bad("O título é obrigatório."); var l = await db.Lessons.Include(x => x.Course).SingleOrDefaultAsync(x => x.Id == req.LessonId && x.Course.StudyGroupId == u.StudyGroupId); if (l is null) return NotFoundError("Aula não encontrada."); var n = new Note { LessonId = l.Id, AuthorId = u.Id, Title = req.Title.Trim() }; db.Notes.Add(n); await db.SaveChangesAsync(); return Results.Created($"/api/notes/{n.Id}", Dtos.Note(n, "author")); });
app.MapGet("/api/notes", async (int? lessonId, HttpContext ctx, AppDbContext db) => { var u = await RequireUser(ctx, db); if (u is null) return Unauthorized(); var q = db.Notes.AsNoTracking().Where(n => n.AuthorId == u.Id || n.Collaborators.Any(c => c.UserId == u.Id)); if (lessonId.HasValue) q = q.Where(n => n.LessonId == lessonId.Value); var list = await q.OrderByDescending(n => n.UpdatedAt).Select(n => new NoteSummaryDto(n.Id,n.LessonId,n.Title,n.AuthorId,n.AuthorId == u.Id ? "author" : n.Collaborators.Where(c => c.UserId == u.Id).Select(c => c.Permission).FirstOrDefault()!,n.UpdatedAt)).ToListAsync(); return Results.Ok(list); });
app.MapGet("/api/notes/{noteId:long}", async (long noteId, HttpContext ctx, AppDbContext db) => { var u = await RequireUser(ctx, db); if (u is null) return Unauthorized(); var n = await db.Notes.AsNoTracking().Include(x => x.Collaborators).SingleOrDefaultAsync(x => x.Id == noteId); if (n is null) return NotFoundError("Apontamento não encontrado."); var p = Permission(n,u.Id); if (p is null) return Forbidden("Sem acesso ao apontamento."); return Results.Ok(Dtos.Note(n,p)); });
app.MapGet("/api/notes/{noteId:long}/blocks", async (long noteId, HttpContext ctx, AppDbContext db) => { var u = await RequireUser(ctx, db); if (u is null) return Unauthorized(); var n = await db.Notes.AsNoTracking().Include(x => x.Collaborators).SingleOrDefaultAsync(x => x.Id == noteId); if (n is null) return NotFoundError("Apontamento não encontrado."); if (Permission(n,u.Id) is null) return Forbidden("Sem acesso ao apontamento."); return Results.Ok(await db.NoteBlocks.AsNoTracking().Where(x => x.NoteId == noteId).OrderBy(x => x.Position).Select(x => new { id=x.Id, position=x.Position, content=x.Content, isHighlighted=x.IsHighlighted, changedBy=x.ChangedBy, changedAt=x.ChangedAt }).ToListAsync()); });
app.MapPost("/api/notes/{noteId:long}/blocks", async (long noteId, BlocksRequest req, HttpContext ctx, AppDbContext db) => { var u = await RequireUser(ctx, db); if (u is null) return Unauthorized(); var n = await db.Notes.Include(x => x.Collaborators).SingleOrDefaultAsync(x => x.Id == noteId); if (n is null) return NotFoundError("Apontamento não encontrado."); if (!CanEdit(n,u.Id)) return Forbidden("É necessária permissão de edição."); if (req.Blocks is null || req.Blocks.Count == 0 || req.Blocks.Any(x => string.IsNullOrWhiteSpace(x.Content))) return Bad("Os blocos não podem estar vazios."); if (req.TranscriptionId.HasValue && !await db.Transcriptions.AnyAsync(t => t.Id == req.TranscriptionId.Value && t.Job.Status == "Completed")) return Conflict("A transcrição não está concluída."); var pos = await db.NoteBlocks.Where(x => x.NoteId == noteId).Select(x => (int?)x.Position).MaxAsync() ?? 0; var blocks = req.Blocks.Select((b,i) => new NoteBlock { NoteId = noteId, Position = ++pos, Content = b.Content.Trim(), ChangedBy = u.Id }).ToList(); db.NoteBlocks.AddRange(blocks); n.UpdatedAt = DateTime.UtcNow; await db.SaveChangesAsync(); return Results.Created($"/api/notes/{noteId}/blocks", blocks.Select(Dtos.Block)); });
app.MapPut("/api/notes/{noteId:long}/blocks/{blockId:long}", async (long noteId, long blockId, BlockUpdate req, HttpContext ctx, AppDbContext db) => { var u = await RequireUser(ctx, db); if (u is null) return Unauthorized(); var n = await db.Notes.Include(x => x.Collaborators).SingleOrDefaultAsync(x => x.Id == noteId); var b = await db.NoteBlocks.SingleOrDefaultAsync(x => x.Id == blockId && x.NoteId == noteId); if (n is null || b is null) return NotFoundError("Bloco não encontrado."); if (!CanEdit(n,u.Id)) return Forbidden("É necessária permissão de edição."); if (req.Content is not null) { if (string.IsNullOrWhiteSpace(req.Content)) return Bad("O conteúdo não pode estar vazio."); b.Content = req.Content.Trim(); } if (req.IsHighlighted.HasValue) b.IsHighlighted = req.IsHighlighted.Value; b.ChangedBy = u.Id; b.ChangedAt = DateTime.UtcNow; n.UpdatedAt = DateTime.UtcNow; var recipients = n.Collaborators.Where(c => c.UserId != u.Id).Select(c => c.UserId).Append(n.AuthorId).Distinct().ToList(); foreach (var id in recipients) db.Notifications.Add(new Notification { UserId = id, NoteId = n.Id, Type = "NoteEdited", Message = "Um apontamento partilhado foi atualizado." }); await db.SaveChangesAsync(); return Results.Ok(Dtos.Block(b)); });

app.MapPost("/api/lessons/{lessonId:long}/audio", async (long lessonId, HttpRequest request, HttpContext ctx, AppDbContext db, IConfiguration cfg) => { var u = await RequireUser(ctx, db); if (u is null) return Unauthorized(); var lesson = await db.Lessons.Include(x => x.Course).SingleOrDefaultAsync(x => x.Id == lessonId && x.Course.StudyGroupId == u.StudyGroupId); if (lesson is null) return NotFoundError("Aula não encontrada."); if (!request.HasFormContentType) return Bad("É necessário multipart/form-data."); var form = await request.ReadFormAsync(); var file = form.Files.GetFile("file"); if (file is null || file.Length == 0) return Bad("Ficheiro obrigatório."); var max = cfg.GetValue<long?>("Uploads:MaxBytes") ?? 100 * 1024 * 1024; if (file.Length > max) return Results.StatusCode(413)!; var allowed = new[] { ".mp3", ".wav", ".m4a", ".webm", ".ogg" }; var ext = Path.GetExtension(file.FileName).ToLowerInvariant(); if (!allowed.Contains(ext)) return Results.StatusCode(415)!; var root = cfg["Uploads:Path"] ?? Path.Combine(AppContext.BaseDirectory, "uploads"); Directory.CreateDirectory(root); var safe = $"{Guid.NewGuid():N}{ext}"; var path = Path.Combine(root, safe); await using (var stream = File.Create(path)) await file.CopyToAsync(stream); var audio = new AudioRecording { LessonId = lessonId, UploadedBy = u.Id, FilePath = path, FileFormat = ext[1..], SizeBytes = file.Length }; var job = new TranscriptionJob { AudioRecording = audio, Status = "Pending" }; db.Add(job); await db.SaveChangesAsync(); return Results.Created($"/api/transcription-jobs/{job.Id}", new { audioRecordingId = audio.Id, transcriptionJobId = job.Id, status = job.Status }); });
app.MapGet("/api/transcription-jobs/{jobId:long}", async (long jobId, HttpContext ctx, AppDbContext db) => { var u = await RequireUser(ctx, db); if (u is null) return Unauthorized(); var j = await db.TranscriptionJobs.AsNoTracking().Include(x => x.AudioRecording).SingleOrDefaultAsync(x => x.Id == jobId); if (j is null) return NotFoundError("Tarefa não encontrada."); if (!await HasLessonAccess(db,j.AudioRecording.LessonId,u.Id)) return Forbidden("Sem acesso."); return Results.Ok(Dtos.Job(j)); });
app.MapGet("/api/transcriptions/{id:long}", async (long id, HttpContext ctx, AppDbContext db) => { var u = await RequireUser(ctx, db); if (u is null) return Unauthorized(); var t = await db.Transcriptions.AsNoTracking().Include(x => x.Job).ThenInclude(x => x.AudioRecording).SingleOrDefaultAsync(x => x.Id == id); if (t is null) return NotFoundError("Transcrição não encontrada."); if (!await HasLessonAccess(db,t.Job.AudioRecording.LessonId,u.Id)) return Forbidden("Sem acesso."); return Results.Ok(new { t.Id, t.Text, t.Language, t.CreatedAt }); });
app.MapPost("/api/audio/{audioId:long}/retry", async (long audioId, HttpContext ctx, AppDbContext db) => { var u = await RequireUser(ctx, db); if (u is null) return Unauthorized(); var a = await db.AudioRecordings.Include(x => x.Lesson).ThenInclude(x => x.Course).Include(x => x.TranscriptionJobs).SingleOrDefaultAsync(x => x.Id == audioId); if (a is null || a.UploadedBy != u.Id) return NotFoundError("Gravação não encontrada."); if (a.TranscriptionJobs.OrderByDescending(x => x.CreatedAt).FirstOrDefault()?.Status != "Failed") return Conflict("Só é possível repetir uma tarefa falhada."); var j = new TranscriptionJob { AudioRecordingId = audioId, Status = "Pending" }; db.Add(j); await db.SaveChangesAsync(); return Results.Created($"/api/transcription-jobs/{j.Id}", new { transcriptionJobId = j.Id, status = j.Status }); });

app.MapGet("/api/notes/{noteId:long}/collaborators", async (long noteId, HttpContext ctx, AppDbContext db) => { var u = await RequireUser(ctx, db); if (u is null) return Unauthorized(); var n = await db.Notes.SingleOrDefaultAsync(x => x.Id == noteId); if (n is null) return NotFoundError("Apontamento não encontrado."); if (n.AuthorId != u.Id) return Forbidden("Só o autor gere a partilha."); return Results.Ok(await db.NoteCollaborators.Where(x => x.NoteId == noteId).Select(x => new { userId = x.UserId, fullName = x.User.FullName, permission = x.Permission }).ToListAsync()); });
app.MapPost("/api/notes/{noteId:long}/collaborators", async (long noteId, CollaboratorRequest req, HttpContext ctx, AppDbContext db) => { var u = await RequireUser(ctx, db); if (u is null) return Unauthorized(); var n = await db.Notes.SingleOrDefaultAsync(x => x.Id == noteId); if (n is null) return NotFoundError("Apontamento não encontrado."); if (n.AuthorId != u.Id) return Forbidden("Só o autor gere a partilha."); if (!new[] { "read", "comment", "edit" }.Contains(req.Permission)) return Bad("Permissão inválida."); var target = await db.Users.SingleOrDefaultAsync(x => x.Id == req.UserId && x.StudyGroupId == u.StudyGroupId); if (target is null) return NotFoundError("Utilizador não encontrado."); if (await db.NoteCollaborators.AnyAsync(x => x.NoteId == noteId && x.UserId == req.UserId)) return Conflict("Acesso já concedido."); var c = new NoteCollaborator { NoteId = noteId, UserId = req.UserId, Permission = req.Permission }; db.Add(c); await db.SaveChangesAsync(); return Results.Created($"/api/notes/{noteId}/collaborators/{req.UserId}", new { userId = c.UserId, permission = c.Permission }); });
app.MapDelete("/api/notes/{noteId:long}/collaborators/{userId:long}", async (long noteId, long userId, HttpContext ctx, AppDbContext db) => { var u = await RequireUser(ctx, db); if (u is null) return Unauthorized(); var n = await db.Notes.SingleOrDefaultAsync(x => x.Id == noteId); if (n is null) return NotFoundError("Apontamento não encontrado."); if (n.AuthorId != u.Id) return Forbidden("Só o autor gere a partilha."); var c = await db.NoteCollaborators.SingleOrDefaultAsync(x => x.NoteId == noteId && x.UserId == userId); if (c is null) return NotFoundError("Colaborador não encontrado."); db.Remove(c); await db.SaveChangesAsync(); return Results.NoContent(); });

app.MapGet("/api/blocks/{blockId:long}/comments", async (long blockId, HttpContext ctx, AppDbContext db) => { var u = await RequireUser(ctx, db); if (u is null) return Unauthorized(); var b = await db.NoteBlocks.Include(x => x.Note).ThenInclude(x => x.Collaborators).SingleOrDefaultAsync(x => x.Id == blockId); if (b is null) return NotFoundError("Bloco não encontrado."); if (Permission(b.Note,u.Id) is null) return Forbidden("Sem acesso."); return Results.Ok(await db.Comments.AsNoTracking().Where(x => x.NoteBlockId == blockId).OrderBy(x => x.CreatedAt).Select(x => new { id=x.Id, authorId=x.AuthorId, authorName=x.Author.FullName, text=x.Text, createdAt=x.CreatedAt }).ToListAsync()); });
app.MapPost("/api/blocks/{blockId:long}/comments", async (long blockId, CommentRequest req, HttpContext ctx, AppDbContext db) => { var u = await RequireUser(ctx, db); if (u is null) return Unauthorized(); if (string.IsNullOrWhiteSpace(req.Text)) return Bad("O comentário não pode estar vazio."); var b = await db.NoteBlocks.Include(x => x.Note).ThenInclude(x => x.Collaborators).SingleOrDefaultAsync(x => x.Id == blockId); if (b is null) return NotFoundError("Bloco não encontrado."); var p = Permission(b.Note,u.Id); if (p is null) return Forbidden("Sem acesso."); if (p is "read") return Forbidden("É necessária permissão de comentário."); var c = new Comment { NoteBlockId = blockId, AuthorId = u.Id, Text = req.Text.Trim() }; db.Add(c); await db.SaveChangesAsync(); await db.Entry(c).Reference(x => x.Author).LoadAsync(); return Results.Created($"/api/blocks/{blockId}/comments/{c.Id}", Dtos.Comment(c)); });

app.MapGet("/api/notifications", async (bool? unreadOnly, HttpContext ctx, AppDbContext db) => { var u = await RequireUser(ctx, db); if (u is null) return Unauthorized(); var q = db.Notifications.AsNoTracking().Where(x => x.UserId == u.Id); if (unreadOnly == true) q = q.Where(x => !x.IsRead); return Results.Ok(await q.OrderByDescending(x => x.CreatedAt).Select(x => new { x.Id, x.Type, x.Message, x.NoteId, x.IsRead, x.CreatedAt }).ToListAsync()); });
app.MapPatch("/api/notifications/{id:long}/read", async (long id, HttpContext ctx, AppDbContext db) => { var u = await RequireUser(ctx, db); if (u is null) return Unauthorized(); var n = await db.Notifications.SingleOrDefaultAsync(x => x.Id == id && x.UserId == u.Id); if (n is null) return NotFoundError("Notificação não encontrada."); n.IsRead = true; await db.SaveChangesAsync(); return Results.NoContent(); });
app.MapPatch("/api/notifications/read-all", async (HttpContext ctx, AppDbContext db) => { var u = await RequireUser(ctx, db); if (u is null) return Unauthorized(); await db.Notifications.Where(x => x.UserId == u.Id && !x.IsRead).ExecuteUpdateAsync(s => s.SetProperty(x => x.IsRead, true)); return Results.NoContent(); });

app.Run();

static IResult Bad(string message) => Results.BadRequest(new { error = message });
static IResult Conflict(string message) => Results.Conflict(new { error = message });
static IResult Forbidden(string message) => Results.Json(new { error = message }, statusCode: 403);
static IResult Unauthorized() => Results.Json(new { error = "Autenticação necessária." }, statusCode: 401);
static IResult NotFoundError(string message) => Results.NotFound(new { error = message });
static User? Require(HttpContext ctx) => ctx.User.Identity?.IsAuthenticated == true ? new User { Id = long.Parse(ctx.User.FindFirstValue(ClaimTypes.NameIdentifier)!) } : null;
static async Task<User?> RequireUser(HttpContext ctx, AppDbContext db) { var principal = Require(ctx); return principal is null ? null : await db.Users.SingleOrDefaultAsync(x => x.Id == principal.Id); }
static string? Permission(Note n, long uid) => n.AuthorId == uid ? "author" : n.Collaborators.FirstOrDefault(x => x.UserId == uid)?.Permission;
static bool CanEdit(Note n, long uid) => Permission(n, uid) is "author" or "edit";
static async Task<bool> HasLessonAccess(AppDbContext db, long lessonId, long uid) => await db.Lessons.Where(l => l.Id == lessonId).AnyAsync(l => l.Course.StudyGroup.Users.Any(u => u.Id == uid));

public record RegisterRequest(string FullName, string Email, string Password, long StudyGroupId) { public string? Validate() => string.IsNullOrWhiteSpace(FullName) || FullName.Length > 200 ? "Nome inválido." : string.IsNullOrWhiteSpace(Email) || !Email.Contains('@') ? "E-mail inválido." : string.IsNullOrWhiteSpace(Password) || Password.Length < 8 ? "A palavra-passe deve ter pelo menos 8 caracteres." : null; }
public record LoginRequest(string Email, string Password);
public record CourseRequest(string Title); public record LessonRequest(string Topic, string LessonDate); public record NoteRequest(long LessonId, string Title); public record BlockInput(string Content); public record BlocksRequest(List<BlockInput> Blocks, long? TranscriptionId); public record BlockUpdate(string? Content, bool? IsHighlighted); public record CollaboratorRequest(long UserId, string Permission); public record CommentRequest(string Text);
public record NoteSummaryDto(long Id,long LessonId,string Title,long AuthorId,string MyPermission,DateTime UpdatedAt);

static class Dtos
{
    public static object User(User u) => new { id = u.Id, fullName = u.FullName, email = u.Email, studyGroupId = u.StudyGroupId };
    public static object Lesson(Lesson l) => new { id = l.Id, courseId = l.CourseId, topic = l.Topic, lessonDate = l.LessonDate.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture) };
    public static object Note(Note n,string permission) => new { id=n.Id, lessonId=n.LessonId, authorId=n.AuthorId, title=n.Title, myPermission=permission, createdAt=n.CreatedAt, updatedAt=n.UpdatedAt };
    public static object Block(NoteBlock b) => new { id=b.Id, position=b.Position, content=b.Content, isHighlighted=b.IsHighlighted, changedBy=b.ChangedBy, changedAt=b.ChangedAt };
    public static object Comment(Comment c) => new { id=c.Id, authorId=c.AuthorId, authorName=c.Author?.FullName ?? "", text=c.Text, createdAt=c.CreatedAt };
    public static object Job(TranscriptionJob j) => new { id=j.Id, audioRecordingId=j.AudioRecordingId, status=j.Status, errorMessage=j.ErrorMessage, createdAt=j.CreatedAt, finishedAt=j.FinishedAt, transcriptionId=j.Transcription?.Id };
}

public class StudyGroup { public long Id {get;set;} [MaxLength(100)] public string Name {get;set;}=""; public DateTime CreatedAt {get;set;}=DateTime.UtcNow; public ICollection<User> Users {get;set;}=[]; public ICollection<Course> Courses {get;set;}=[]; }
public class User { public long Id {get;set;} [MaxLength(200)] public string FullName {get;set;}=""; [MaxLength(255)] public string Email {get;set;}=""; [MaxLength(255)] public string PasswordHash {get;set;}=""; public long? StudyGroupId {get;set;} public StudyGroup? StudyGroup {get;set;} public DateTime CreatedAt {get;set;}=DateTime.UtcNow; public ICollection<Note> Notes {get;set;}=[]; public ICollection<NoteCollaborator> Collaborations {get;set;}=[]; public ICollection<Comment> Comments {get;set;}=[]; public ICollection<Notification> Notifications {get;set;}=[]; }
public class Course { public long Id {get;set;} public long StudyGroupId {get;set;} public StudyGroup StudyGroup {get;set;}=null!; [MaxLength(200)] public string Title {get;set;}=""; public ICollection<Lesson> Lessons {get;set;}=[]; }
public class Lesson { public long Id {get;set;} public long CourseId {get;set;} public Course Course {get;set;}=null!; [MaxLength(255)] public string Topic {get;set;}=""; public DateOnly LessonDate {get;set;} public ICollection<Note> Notes {get;set;}=[]; public ICollection<AudioRecording> AudioRecordings {get;set;}=[]; }
public class Note { public long Id {get;set;} public long LessonId {get;set;} public Lesson Lesson {get;set;}=null!; public long AuthorId {get;set;} public User Author {get;set;}=null!; [MaxLength(255)] public string Title {get;set;}=""; public DateTime CreatedAt {get;set;}=DateTime.UtcNow; public DateTime UpdatedAt {get;set;}=DateTime.UtcNow; public ICollection<NoteBlock> Blocks {get;set;}=[]; public ICollection<NoteCollaborator> Collaborators {get;set;}=[]; public ICollection<Notification> Notifications {get;set;}=[]; }
public class AudioRecording { public long Id {get;set;} public long LessonId {get;set;} public Lesson Lesson {get;set;}=null!; public long UploadedBy {get;set;} public User Uploader {get;set;}=null!; [MaxLength(500)] public string FilePath {get;set;}=""; [MaxLength(10)] public string FileFormat {get;set;}=""; public long SizeBytes {get;set;} public DateTime UploadedAt {get;set;}=DateTime.UtcNow; public ICollection<TranscriptionJob> TranscriptionJobs {get;set;}=[]; }
public class TranscriptionJob { public long Id {get;set;} public long AudioRecordingId {get;set;} public AudioRecording AudioRecording {get;set;}=null!; [MaxLength(20)] public string Status {get;set;}="Pending"; public string? ErrorMessage {get;set;} public DateTime CreatedAt {get;set;}=DateTime.UtcNow; public DateTime? FinishedAt {get;set;} public Transcription? Transcription {get;set;} }
public class Transcription { public long Id {get;set;} public long TranscriptionJobId {get;set;} public TranscriptionJob Job {get;set;}=null!; public string Text {get;set;}=""; [MaxLength(10)] public string Language {get;set;}="pt"; public DateTime CreatedAt {get;set;}=DateTime.UtcNow; }
public class NoteBlock { public long Id {get;set;} public long NoteId {get;set;} public Note Note {get;set;}=null!; public int Position {get;set;} public string Content {get;set;}=""; public bool IsHighlighted {get;set;} public long? ChangedBy {get;set;} public User? ChangedByUser {get;set;} public DateTime ChangedAt {get;set;}=DateTime.UtcNow; public ICollection<Comment> Comments {get;set;}=[]; }
public class NoteCollaborator { public long Id {get;set;} public long NoteId {get;set;} public Note Note {get;set;}=null!; public long UserId {get;set;} public User User {get;set;}=null!; [MaxLength(10)] public string Permission {get;set;}="read"; }
public class Comment { public long Id {get;set;} public long NoteBlockId {get;set;} public NoteBlock NoteBlock {get;set;}=null!; public long AuthorId {get;set;} public User Author {get;set;}=null!; public string Text {get;set;}=""; public DateTime CreatedAt {get;set;}=DateTime.UtcNow; }
public class Notification { public long Id {get;set;} public long UserId {get;set;} public User User {get;set;}=null!; public long? NoteId {get;set;} public Note? Note {get;set;} [MaxLength(30)] public string Type {get;set;}=""; [MaxLength(500)] public string Message {get;set;}=""; public bool IsRead {get;set;} public DateTime CreatedAt {get;set;}=DateTime.UtcNow; }

public class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options)
{
    public DbSet<StudyGroup> StudyGroups => Set<StudyGroup>(); public DbSet<User> Users=>Set<User>(); public DbSet<Course> Courses=>Set<Course>(); public DbSet<Lesson> Lessons=>Set<Lesson>(); public DbSet<Note> Notes=>Set<Note>(); public DbSet<AudioRecording> AudioRecordings=>Set<AudioRecording>(); public DbSet<TranscriptionJob> TranscriptionJobs=>Set<TranscriptionJob>(); public DbSet<Transcription> Transcriptions=>Set<Transcription>(); public DbSet<NoteBlock> NoteBlocks=>Set<NoteBlock>(); public DbSet<NoteCollaborator> NoteCollaborators=>Set<NoteCollaborator>(); public DbSet<Comment> Comments=>Set<Comment>(); public DbSet<Notification> Notifications=>Set<Notification>();
    protected override void OnModelCreating(ModelBuilder b) { b.Entity<User>().HasIndex(x=>x.Email).IsUnique(); b.Entity<StudyGroup>().HasIndex(x=>x.Name).IsUnique(); b.Entity<NoteCollaborator>().HasIndex(x=>new{x.NoteId,x.UserId}).IsUnique(); b.Entity<NoteBlock>().HasIndex(x=>new{x.NoteId,x.Position}).IsUnique(); b.Entity<Transcription>().HasIndex(x=>x.TranscriptionJobId).IsUnique(); b.Entity<TranscriptionJob>().HasOne(x=>x.Transcription).WithOne(x=>x.Job).HasForeignKey<Transcription>(x=>x.TranscriptionJobId); b.Entity<Note>().HasOne(x=>x.Author).WithMany(x=>x.Notes).HasForeignKey(x=>x.AuthorId).OnDelete(DeleteBehavior.Restrict); b.Entity<Notification>().HasOne(x=>x.Note).WithMany(x=>x.Notifications).HasForeignKey(x=>x.NoteId).OnDelete(DeleteBehavior.Cascade); b.Entity<NoteBlock>().HasOne(x=>x.ChangedByUser).WithMany().HasForeignKey(x=>x.ChangedBy).OnDelete(DeleteBehavior.SetNull); b.Entity<AudioRecording>().HasOne(x=>x.Uploader).WithMany().HasForeignKey(x=>x.UploadedBy).OnDelete(DeleteBehavior.Restrict); }
}

public sealed class TokenService(IConfiguration cfg)
{
    private readonly byte[] key = Encoding.UTF8.GetBytes(cfg["Auth:SigningKey"] ?? "lectnote-development-signing-key-change-in-production");
    public string Create(User u) { var payload = $"{u.Id}:{DateTimeOffset.UtcNow.AddHours(12).ToUnixTimeSeconds()}"; var data=Convert.ToBase64String(Encoding.UTF8.GetBytes(payload)).TrimEnd('='); using var h=new HMACSHA256(key); return $"{data}.{Convert.ToBase64String(h.ComputeHash(Encoding.UTF8.GetBytes(data))).Replace('+','-').Replace('/','_').TrimEnd('=')}"; }
    public bool TryRead(string token, out long id) { id=0; var p=token.Split('.'); if(p.Length!=2)return false; using var h=new HMACSHA256(key); var expected=Convert.ToBase64String(h.ComputeHash(Encoding.UTF8.GetBytes(p[0]))).Replace('+','-').Replace('/','_').TrimEnd('='); if(!CryptographicOperations.FixedTimeEquals(Encoding.UTF8.GetBytes(expected),Encoding.UTF8.GetBytes(p[1])))return false; try { var s=Encoding.UTF8.GetString(Convert.FromBase64String(p[0]+new string('=',(4-p[0].Length%4)%4))).Split(':'); id=long.Parse(s[0]); return DateTimeOffset.UtcNow.ToUnixTimeSeconds()<long.Parse(s[1]); } catch{return false;} }
}
static class AuthMiddleware { public static Task TrySetUser(HttpContext c, TokenService t) { var h=c.Request.Headers.Authorization.ToString(); if(h.StartsWith("Bearer ")&&t.TryRead(h[7..],out var id)) c.User=new ClaimsPrincipal(new ClaimsIdentity([new Claim(ClaimTypes.NameIdentifier,id.ToString())],"Bearer")); return Task.CompletedTask; } }

public sealed class TranscriptionWorker(IServiceScopeFactory scopes, ILogger<TranscriptionWorker> log) : BackgroundService
{ protected override async Task ExecuteAsync(CancellationToken stop) { while(!stop.IsCancellationRequested) { try { using var s=scopes.CreateScope(); var db=s.ServiceProvider.GetRequiredService<AppDbContext>(); var service=s.ServiceProvider.GetRequiredService<OpenAiTranscriptionService>(); var jobs=await db.TranscriptionJobs.Include(x=>x.AudioRecording).Where(x=>x.Status=="Pending").OrderBy(x=>x.CreatedAt).Take(2).ToListAsync(stop); foreach(var j in jobs) { try { j.Status="Pending"; var result=await service.TranscribeAsync(j.AudioRecording.FilePath, j.AudioRecording.FileFormat, stop); j.Status="Completed"; j.FinishedAt=DateTime.UtcNow; j.Transcription=new Transcription { Text=result.Text, Language=result.Language }; db.Notifications.Add(new Notification { UserId=j.AudioRecording.UploadedBy, Type="TranscriptionCompleted", Message="A transcrição está pronta." }); } catch(Exception ex) { j.Status="Failed"; j.FinishedAt=DateTime.UtcNow; j.ErrorMessage="Não foi possível processar o áudio."; log.LogWarning(ex,"Transcription job {JobId} failed",j.Id); } await db.SaveChangesAsync(stop); } } catch(Exception ex) { log.LogError(ex,"Transcription worker iteration failed"); } await Task.Delay(TimeSpan.FromSeconds(5),stop); } } }
public sealed record TranscriptionResult(string Text,string Language);
public sealed class OpenAiTranscriptionService(HttpClient http, IConfiguration cfg)
{ public async Task<TranscriptionResult> TranscribeAsync(string path,string format,CancellationToken ct) { var key=cfg["OpenAI:ApiKey"] ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY"); if(string.IsNullOrWhiteSpace(key)) throw new InvalidOperationException("OpenAI transcription credentials are not configured."); using var form=new MultipartFormDataContent(); using var fs=File.OpenRead(path); var file=new StreamContent(fs); file.Headers.ContentType=new MediaTypeHeaderValue($"audio/{format}"); form.Add(file,"file",Path.GetFileName(path)); form.Add(new StringContent(cfg["OpenAI:Model"] ?? "whisper-1"),"model"); var req=new HttpRequestMessage(HttpMethod.Post,cfg["OpenAI:BaseUrl"] ?? "https://api.openai.com/v1/audio/transcriptions"){Content=form}; req.Headers.Authorization=new AuthenticationHeaderValue("Bearer",key); var res=await http.SendAsync(req,ct); if(!res.IsSuccessStatusCode) throw new InvalidOperationException($"Transcription provider returned {(int)res.StatusCode}."); using var doc=JsonDocument.Parse(await res.Content.ReadAsStringAsync(ct)); return new(doc.RootElement.GetProperty("text").GetString() ?? "",cfg["Transcription:DefaultLanguage"] ?? "pt"); } }
